find_rule:
js:
var d = [];
var j = JSON.parse(getResCode());
var l = (j.data && (j.data.list || j.data.content || j.data)) || [];
for (var i = 0; i < l.length; i++) {
  var it = l[i];
  d.push({
    title: it.title || it.name || '',
    desc: it.count || it.remarks || '',
    img: (it.cover || it.pic || it.img || '') + '@Referer=https://example.com',
    url: 'https://example.com/album?id=' + (it.id || ''),
    col_type: 'movie_3'
  });
}
setResult(d);

